// EN translation FIRST PASS. Literary editorial approval outstanding.
const OUTCOMES_EN_E291_E360 = Object.freeze({"E291.1":{"s":"The king goes against Arr and forces the lion to accept the outcome of the duel. The baron pays in gold for the unexpectedly saved fort.","f":"Arr knocks the King to the ground, seriously injuring him. The Baron looks away from the field.","v":{"nf":"The duel is interrupted without the King being gravely wounded, but the dispute over the fort remains open."}},"E291.2":{"s":"You return your own words to the baron, and he is forced to personally come to an agreement with Arr. The baron pays in gold for his release from the royal duel.","f":"The Baron declares your demand treason against the human side and withdraws the guards. A skirmish begins."},"E291.3":{"s":"You pay for the day of truce for both rulers. Arr sits down at the border, and for the first time that morning the baron unfolds the map instead of the sword."},"E291.4":{"s":"You refuse to represent the baron in someone else's fight. Arr turns to the one he actually called."},"E292.1":{"s":"You buy supplies from Pip, and Roach receives another cake for the transaction. The goblin immediately offers a paid dragon smile."},"E292.2":{"s":"You are trying to get Roach to let passers-by go without buying anything. Pip returns some of the wrongfully taken gold.","f":"The dragon mistakes the demand for an attempt to deprive him of the cakes and calls the kiosk guards. A skirmish begins."},"E292.3":{"s":"{{heroName}} engages Roach in conversation about his favorite cakes, and customers manage to get in for free. Pip is paid off with gold to stop the flow of complaints.","f":"Roach turns sharply towards the distraction, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The dragon stops the diversion, but none of the eligible fighters are gravely wounded. The kiosk continues to demand purchase."}},"E292.4":{"s":"You go around the kiosk on the other side of the road. Roach follows the party with his eyes, and Pip is already posting the price for the detour."},"E293.1":{"s":"Edran agrees to temporarily take in K-12 and gives him a simple job at the blacksmith shop. The grateful machine gun finds supplies for the party.","f":"The blacksmith is not ready to call the owner of a golem that is two centuries older than him. K-12 remains to wait for the order."},"E293.2":{"s":"You disable K-12 without damaging the workshop and take valuable parts for gold.","f":"The golem declares the shutdown an attack on the owner and raises its metal arms. A skirmish begins."},"E293.3":{"s":"{{heroName}} finds an old note about Edran's name and a hidden gold bookmark on the plate. The blacksmith gets at least part of the answer.","f":"The plate closes on the instruments, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The plate protects the mechanism's memory, but no eligible combatants are gravely wounded. The recording remains a mystery."}},"E293.4":{"s":"You walk past the blacksmith shop and don't give orders to K-12. Every few steps the same “What’s the order?” is heard."},"E294.1":{"s":"You allow the skeletons to remain at the fair with already purchased tickets. Grateful pie merchants supply the party with supplies.","f":"The headman does not dare to change the rule about signs of life and leaves the undead in front of the gate. The fair continues to argue."},"E294.2":{"s":"You return the price of the tickets to the skeletons from your treasury. One visitor reluctantly gives up his spoon and goes to the exit."},"E294.3":{"s":"{{heroName}} finds in the charter a definition of a guest as the holder of a valid ticket, which does not specify the condition of the bones. The headman pays in gold and supplies.","f":"{{heroName}} finds two conflicting articles about guests and dead people. The decision has to be postponed until the next fair."},"E294.4":{"s":"You leave the fair where skeletons are trying to buy pies and merchants are trying to sell them hats. The headman is still looking for the correct form."},"E295.1":{"s":"You secure permission to cut down the infested tree, and the dwarves finally take up their axes. Sin thanks the supplies for preventing the disease.","f":"Neighboring keepers refuse to acknowledge the threat without evidence. The cutting has to be stopped."},"E295.2":{"s":"You leave Sin and the dwarves in front of the diseased tree. No one has yet decided to be the first to put the ax on the trunk."},"E295.3":{"s":"{{heroName}} shows everyone signs of disease on the bark and roots, after which Sin gains the right to stop the infection. The party is rewarded with gold and supplies.","f":"{{heroName}} finds evidence of two similar diseases, but cannot determine whether one is threatening neighboring trees. Felling is postponed."},"E295.4":{"s":"You pay the dwarves to work on behalf of the King, and they remove the infested tree in front of witnesses. Sin supplies the party with supplies."},"E296.1":{"s":"You hold the light circle until dawn, and the pursuers leave without Saar. Elion donates supplies for keeping the oath.","f":"The demons break through the ring of light before the sun rises. The battle begins."},"E296.2":{"s":"You accept the gold of your pursuers and move away from the light circle. Elion is left alone to defend the unarmed Saar."},"E296.3":{"s":"You give your pursuers the gold, and they retreat before dawn. Elion does not lower the light border until the last demon disappears."},"E296.4":{"s":"You leave the angel to hold the refuge with your oath. Saar remains silent as the shadows of his pursuers lengthen around the circle."},"E297.1":{"s":"You help the village strengthen the dam near the river, and the residents thank you for the preparations with supplies.","f":"The dam does not have time to rise to the required height, and supplies are wasted on unnecessary work. Oren still promises flooding."},"E297.2":{"s":"You help stockpile water in case of drought, and the villagers pay in gold for their forethought.","f":"Tilly cannot indicate where to look for water underground. Preparation brings no reward."},"E297.3":{"s":"{{heroName}} finds out that both prophets are talking about different hours of tomorrow. The village is preparing for both water and dry land, issuing gold and supplies.","f":"{{heroName}} cannot determine when exactly the prophetic “tomorrow” will begin. The village remains between the dam and the well."},"E297.4":{"s":"You leave Oren with the clouds and Tilly with the cracks in the east. The village makes two plans for one day."},"E298.1":{"s":"You take the black goat from the sight of three armies and return it to the shepherd. He thanks the supplies for the averted battle.","f":"One of the commanders declares the removal of the goat a violation of the sacred sign. A skirmish begins."},"E298.2":{"s":"The Goat approaches the King, and the armies take this as a sign to stop the rivalry. The leaders pay gold for unexpected mediation.","f":"The three armies accept the goat's coming to the King as a common challenge. Instead of silence, a battle begins."},"E298.3":{"s":"You pay the shepherd for a goat and take him away from the plain before the generals find a new reason for the sign. The animal calmly chews grass."},"E298.4":{"s":"You use up supplies to go around three armies and one goat. The commanders continue to wait to see who he will pay attention to."},"E299.1":{"s":"You sell torn straps, empty boxes and old shoelaces to traders. On Buyer's Day they actually give gold for this.","f":"The traders finally realize that they are buying junk and don't bid anymore. The sale is cancelled."},"E299.2":{"s":"You buy supplies from tired merchants that they are ready to sell at the regular price. The holiday had clearly gone on for them."},"E299.3":{"s":"{{heroName}} finds a buyer who is willing to offer the most for a broken camping spoon. The party receives gold.","f":"{{heroName}} is late: the most desperate merchant has already spent his last coins. There is no good deal."},"E299.4":{"s":"You leave a market where everyone wants to buy other people's unnecessary things. Behind them, two merchants are arguing about a bent fork."},"E300.1":{"s":"You find a cache of gold near a broken cart and see that the traces of all four witnesses really converge here.","f":"At the site of the missing caravan, you are met by armed men hiding among the trees. The battle begins."},"E300.2":{"s":"You pay four travelers for their stories and receive the supplies they saved after the night. The stories remain inconsistent."},"E300.3":{"s":"{{heroName}} compares the four versions and finds where each describes a different part of the attack. At the cart, the party receives gold and supplies.","f":"{{heroName}} discovers that each witness has the correct detail, but the overall course of events cannot be reconstructed. The culprit remains unknown."},"E300.4":{"s":"You leave the four arguing about the caravan without the bodies. The latest version of the skeleton sounds already at dawn."},"E301.1":{"s":"You force the council to declare Orlen alive in front of the entire city. For the corrected mistake, the captain thanks him with gold, and the orchestra plays a different melody.","f":"The council refuses to postpone the paid funeral and invites Orlen to wait for it to end. There is no recognition."},"E301.2":{"s":"Orlen decides that a new living person will find something to do in the royal campaign. He joins the party.","f":"The captain does not want to leave the city where a monument has already been erected to him. He refuses to join the party.","v":{"rs":"Orlen agrees to leave with the King, but there is no free space. The captain thanks him with gold for the proposed exit."}},"E301.3":{"s":"{{heroName}} convinces the council to leave the monument as a sign of victory, not Orlen's death. The city pays in gold for the saved budget and a living captain.","f":"{{heroName}} cannot reconcile the council with the obvious fact of Orlen's return. For the protracted proceedings they collect gold."},"E301.4":{"s":"You leave Orlen to argue with his own monument. In the square they are already rehearsing a speech about the untimely death of the captain."},"E302.1":{"s":"You protect Nurse while he checks the seals and issues letters to the real recipients. The postman thanks in gold for the saved mail.","f":"One of the impatient men grabs the bag while the others draw their weapons. A skirmish begins."},"E302.2":{"s":"You buy from Nurse the travel supplies left for the postal route. He asks not to touch the black envelope."},"E302.3":{"s":"{{heroName}} strengthens the axle and returns the wheel to its place. Nurse thanks with gold and supplies for the opportunity to complete the delivery.","f":"While lifting the cart, the jack breaks and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The wheel breaks off during repairs, but none of the eligible fighters are gravely wounded. The postal route has not been resumed."}},"E302.4":{"s":"You leave Nurse to sort the letters under the gaze of three suspicious recipients. The black seal remains intact."},"E303.1":{"s":"Martha herself names the one with whom she wants to go further, and the men finally hear the decision not from the King. The family thanks with supplies for the returned right to choose.","f":"Martha asks to postpone the wedding until both suitors stop arguing, but neither listens. The holiday stops."},"E303.2":{"s":"You convince both men not to turn their return from war into a duel. The priest thanks in gold for the preserved peace.","f":"Both suitors declare themselves insulted and call supporters. A skirmish begins."},"E303.3":{"s":"{{heroName}} refuses to begin the ceremony until Martha gives her free consent. The family pays gold to defend her decision.","f":"{{heroName}} does not receive Martha’s clear consent and postpones the ceremony. The festive procession remains on the road."},"E303.4":{"s":"You're touring a wedding where no one asked the bride what she wanted. Eld returns the ceremonial book under his arm."},"E304.1":{"s":"You pay the fine and let Doras knead the dough overnight. By morning, he gives the party fresh bread and supplies."},"E304.2":{"s":"You get an exception for the bakery and the overnight ovens are back in operation. Grateful townspeople share supplies.","f":"The guards demand strict adherence to the decree and do not allow the oven to be opened. The dispute turns into a clash."},"E304.3":{"s":"{{heroName}} organizes a quiet night shift without the rattling of baking trays. Doras bakes bread and supplies the party with supplies.","f":"One of the ovens still rattles in the middle of the night, and the guards confiscate some of the prepared supplies. Supplies are becoming scarce."},"E304.4":{"s":"You leave before the quiet bread riot begins. Outside the gates, the townspeople show very eloquent gestures to the guards."},"E305.1":{"s":"You show customers three incompatible boot sizes, and Fess doesn't have an answer. For stopped deception, the bailiff issues gold.","f":"Fess declares the third boot ceremonial, and customers take his word for it. It is not possible to expose the merchant."},"E305.2":{"s":"You buy supplies from nearby shops while the whole square argues about the size of Asten's legs. Sellers are happy to have at least an ordinary deal."},"E305.3":{"s":"{{heroName}} reveals three seals from different workshops on one “royal” set. Fess returns the gold for the counterfeits.","f":"{{heroName}} cannot refute all the evidence at once, and the merchant charges a fee for the examination. The party loses gold."},"E305.4":{"s":"You allow the market to argue about the three boots of one king. Fess already offers a fourth - “for special occasions.”"},"E306.1":{"s":"You take the recorded confessions of others from the man in the gray cloak and find gold from him for blackmail.","f":"The gray stranger whistles to his assistants, and they rush to save the notes. A skirmish begins."},"E306.2":{"s":"You prevent the line, and people stop confessing to the whole yard. Grateful Olm leaves supplies for the party.","f":"The priest does not believe that the walls are betraying other people’s words, and continues the service. The queue remains eavesdropped."},"E306.3":{"s":"{{heroName}} finds enchanted inserts in the walls that amplify whispers. Olm thanks with gold and supplies for the restored secret of confession.","f":"One of the inserts responds with a magical blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The enchanted wall repels explorers, but no eligible combatants are gravely wounded. Confessions can still be heard outside."}},"E306.4":{"s":"You pass by the chapel without stopping at other people's confessions. The man in the gray cloak continues to write quickly."},"E307.1":{"s":"You help the elves complete their farewell to the oak tree, and keeper Mael shares the supplies. Tivan puts the saw away until the end of the ceremony.","f":"The elves cannot agree whether the tree should be buried or given a new purpose. The ritual does not end."},"E307.2":{"s":"You convince Tivan not to touch the trunk until Mael resolves the issue with the guardians. The lumberjack pays in gold for the delay achieved.","f":"Tivan is afraid of missing out on the wood for the bridge and refuses to wait. The dispute with the elves continues."},"E307.3":{"s":"{{heroName}} discovers that the oak tree's roots have already died and the wood is suitable for a bridge without harming neighboring trees. Mael thanks with gold and supplies.","f":"An attempt to check the inner rings results in a live root being struck, and {{affectedHeroName}} is severely injured.","v":{"nf":"The remaining roots repel explorers, but no eligible combatants are gravely wounded. The conclusion about oak is not ready."}},"E307.4":{"s":"You do not interfere with the farewell of a nine-hundred-year-old oak tree. Tivan is waiting next to the saw, but does not approach the trunk."},"E308.1":{"s":"You help herd an invisible deer to the hunters and return stolen food supplies. The party gets supplies.","f":"An invisible beast breaks through the enclosure, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"An invisible deer knocks down the pen, but no eligible combatants are gravely wounded. The dried apples remain with him."}},"E308.2":{"s":"You leave bait for the invisible deer and pay hunters for their supplies. Veira asks to keep the bags tied."},"E308.3":{"s":"{{heroName}} reads footprints in the snow and finds a lair with stolen things and gold. The hunters thank you for the solution.","f":"In a snowy forest, {{affectedHeroName}} is gravely wounded by a sudden blow from an invisible beast.","v":{"nf":"The invisible beast disrupts the pursuit, but none of the eligible fighters are gravely wounded. The tracks break off again."}},"E308.4":{"s":"You leave it to the invisible deer to conquer the hunters and the apples. Veira ties the bags with double knots."},"E309.1":{"s":"At night, the missing note sounds from the forest, and Lior finally dares to answer. There is gold in the old cache near the bridge.","f":"At the sound of music, armed strangers who have nothing to do with the wife’s memory come out of the forest. A skirmish begins."},"E309.2":{"s":"You pay Lior to show you a safe forest path. He sees off the party with a quiet melody without the last sound."},"E309.3":{"s":"{{heroName}} determines that the answer comes from the old acoustic passage behind the bridge. Lior thanks him with gold and supplies for finding the reason.","f":"An attempt to approach the source of the sound ends with a dangerous blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The hidden sound source repels the scouts, but no eligible combatants are gravely wounded. The last note remains a mystery."}},"E309.4":{"s":"You leave Lior on the bridge with an unfinished melody. For the first time that day he doesn't try to finish it."},"E310.1":{"s":"You pay the gardener for the damage caused by the stolen grapes and release the red fox. Elvar records the case as closed without a confession from the defendant."},"E310.2":{"s":"You give away the supplies to replace the seven bunches of grapes, and Rin comes to terms with the loss. He gives gold for a settled dispute."},"E310.3":{"s":"{{heroName}} shows that the concept of contempt for the fence cannot be proven by the testimony of a fox. The court closes the case and thanks with gold.","f":"{{heroName}} cannot convince Elvar to drop the charge of systematic trespassing. The fox yawns even louder."},"E310.4":{"s":"You leave it to the elven court to decide what the fox thinks about its jurisdiction. The accused calmly licks her other paw."},"E311.1":{"s":"You navigate by the fireplace and find both guests in the room, which has already been a kitchen. Evel pays in gold for the returned guests.","f":"The house rearranges the walls behind it, and {{affectedHeroName}} is gravely wounded when the passage collapses.","v":{"nf":"The rooms close in around the search party, but no eligible combatants are gravely wounded. No guests have been found yet."}},"E311.2":{"s":"You buy travel supplies from Evel without leaving the door. The owner asks to let me know if her living room is found anywhere."},"E311.3":{"s":"{{heroName}} finds motionless load-bearing walls among the changing rooms and leads guests outside. Evel thanks with gold and supplies.","f":"The ceiling moves before {{heroName}} can secure it, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The ceiling falls, but none of the eligible fighters are gravely wounded. The house does not give up missing guests."}},"E311.4":{"s":"You leave Evel with a house that doesn't like its own layout. Behind her, the doorway becomes a window."},"E312.1":{"s":"You manage to make out the lines of dry leaves, and Teyla uses them to point out the cache of supplies.","f":"The leaves whip up like a whirlwind and inflict {{affectedHeroName}} a serious injury.","v":{"nf":"The whirlwind scatters leaves, but no eligible combatants are gravely wounded. The letter cannot be read."}},"E312.2":{"s":"You give Teyla supplies for the community, and she thanks you with gold. The leaves along the road stop forming into lines as we say goodbye."},"E312.3":{"s":"{{heroName}} marks repeated characters and restores the meaning of the letter. Aras pays in gold for reading the message.","f":"{{heroName}} cannot collect the last line: the leaves scatter with each new gust. The addressee remains unknown."},"E312.4":{"s":"You are not responding to the message that the reader chooses. The last line falls apart as soon as the party leaves."},"E313.1":{"s":"The groom suffers a fitting defeat, saving his nose for the wedding portrait. Haga awards gold for a well-done fight.","f":"One blow is stronger than intended, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The fight ends in a dangerous clash, but none of the eligible fighters are gravely wounded. Haga does not accept defeat as worthy."}},"E313.2":{"s":"You give the family supplies in lieu of a duel, and Haga thanks you in gold for taking care of the wedding. Groom is still looking for a suitable opponent."},"E313.3":{"s":"{{heroName}} arranges an exhibition fight, in which Groom loses beautifully, and his nose remains intact. Haga pays in gold.","f":"At a sharp turn, {{affectedHeroName}} is gravely wounded, and the exhibition match has to be interrupted.","v":{"nf":"The exhibition fight is stopped after a dangerous blow, but none of the eligible fighters are gravely wounded. Haga remains dissatisfied."}},"E313.4":{"s":"You wish Groom a successful wedding and leave Haga to evaluate the other opponents. The orc promises to try to lose with dignity."},"E314.1":{"s":"You share the soup between both clans, and for the first time Burg can safely ladle it out. For helping the party, they receive supplies.","f":"The leaders demand that they first decide who owns the cauldron, and refuse to even try the soup. Dinner is getting cold."},"E314.2":{"s":"You pay for the copper cauldron and take away the right to control the dinner. Burg is relieved to hand over supplies to end the argument."},"E314.3":{"s":"{{heroName}} finds an old blacksmith's mark under the handle, and Burg confirms who the order was made to. The clans thank us with gold for the outcome.","f":"{{heroName}} reveals two marks from different craftsmen, and the dispute turns to the origin of each pen. The decision is postponed."},"E314.4":{"s":"You leave while two orc squads form up due to the cold soup. Burg promises to use a ladle to stop any battle."},"E315.1":{"s":"You remove the catchy border from the banner, and the banner no longer stands out from afar as a target. Urk thanks in gold for the preserved relic.","f":"Mada considers the alteration insufficient and still demands that the banner be burned. The party leaves without reward."},"E315.2":{"s":"You buy supplies from the orc camp without approaching the disputed banner. Urk is wondering who will carry him tomorrow."},"E315.3":{"s":"{{heroName}} checks the banner and finds the usual signal paint instead of a curse. Mada gives gold for an explanation.","f":"A protective flash bursts out from the folds of the banner, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The banner flashes dangerously when checked, but no eligible fighters are gravely wounded. The reason has not been revealed."}},"E315.4":{"s":"You leave the orcs a banner whose visibility has long been legendary. Urk moves him even further from the fire."},"E316.1":{"s":"You catch up with the teenagers at the stream and return the stolen drum to Mog. The clan thanks in gold for the absence of a punitive campaign.","f":"The teenagers call their armed older brothers and refuse to return the instrument. A skirmish begins."},"E316.2":{"s":"You convince Sara to replace the punitive campaign with a music lesson for both clans. Mog gives out supplies in gratitude.","f":"Sar demands exemplary punishment and does not want to hear about children's pranks. The army continues to gather."},"E316.3":{"s":"{{heroName}} intercepts the teenagers at the fork before they can ruin the drum. Sar pays the gold.","f":"During the crossing, {{affectedHeroName}} is gravely wounded when the kidnappers try to escape through a dangerous gorge.","v":{"nf":"The interception fails on a dangerous descent, but none of the eligible fighters is gravely wounded. The drum was not returned."}},"E316.4":{"s":"You leave Sarah to listen to the missed fourth strike from afar. Mog covers his face with his hand from the shame of the rhythm."},"E317.1":{"s":"You convince Gekh to return to his family, promising to talk about family demands. The clan pays in gold for his release.","f":"Gekh refuses to exchange three meals a day for family debts. Torr doesn’t know whether to rejoice at such a captive."},"E317.2":{"s":"Gekh decides that in the royal party he can eat porridge and not listen to his relatives. He joins the hike.","f":"Geh asks about the meal schedule and upon hearing the answer, he prefers the cage. Can't hire him.","v":{"rs":"Gekh agrees to leave the cage, but a new fighter cannot be accepted. Relatives pay the party gold for their attempt."}},"E317.3":{"s":"{{heroName}} negotiates for Gekh to return home without previous debts and with the condition of feeding him on time. The clan thanks with gold.","f":"{{heroName}} cannot reconcile his relatives with Gekh’s demands, and Torr demands payment for the prolonged maintenance. The treasury is losing gold."},"E317.4":{"s":"You leave Geh to enjoy the porridge in the cage, and Torr to think about how to drive out the satisfied captive. The clan is still waiting outside."},"E318.1":{"s":"You take one hit from the Collapse and make it through the bridge without being hit back. Blacksmith Oba records another completed tradition.","f":"The club comes down too hard and {{affectedHeroName}} is severely wounded.","v":{"nf":"The blow lands on defense, but none of the eligible fighters are gravely wounded. Failure requires repeating the test."}},"E318.2":{"s":"You pay Krach for a day without hitting and cross the bridge while he looks at the gold he received in surprise."},"E318.3":{"s":"{{heroName}} takes the blow to strong defense and gets the right to lead the party. The collapse thanks in gold for a worthy test.","f":"The club breaks through the counter, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The strike fails to seriously wound an eligible combatant, but Collapse declares the test a failure. There is no reward."}},"E318.4":{"s":"You spend supplies on another crossing without experiencing someone else's club on your own head. Oba watches them leave with obvious approval."},"E319.1":{"s":"You find a name in an old cemetery book that matches the skeleton's memories. He thanks in gold for the returned past.","f":"Vess finds several identical records and cannot determine the correct one. The skeleton refuses to be named at random."},"E319.2":{"s":"You give the skeleton supplies for the journey to his former home, and he shares the gold left with him after death."},"E319.3":{"s":"{{heroName}} restores the erased letters on the tombstone, and the skeleton finally reads his own name. Vess thanks with gold.","f":"The old slab responds with a magical blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The tombstone triggers a protective seal, but no eligible combatants are gravely wounded. The name remains forgotten."}},"E319.4":{"s":"You invite the skeleton to choose a new name without waiting for the old entries to be resolved. He looks thoughtfully at the empty stove."},"E320.1":{"s":"You help the village complete the old funeral words, and the orchestra finally falls silent. Grateful residents give out supplies.","f":"The conductor cannot remember the last verse, and the musicians begin the march again. The ceremony is not over."},"E320.2":{"s":"You pay residents for information about the late owner of the orchestra. Pell listens intently, still conducting."},"E320.3":{"s":"{{heroName}} restores the missing end of the ceremony, and the orchestra concludes the six-day performance. Pell thanks with gold and supplies.","f":"The ritual causes a dangerous response of old magic, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"Funeral magic disrupts the execution, but no eligible combatants are gravely wounded. The orchestra continues the march."}},"E320.4":{"s":"You leave the village until the next verse. Pell, having no lungs, still sighs before the new introduction."},"E321.1":{"s":"You acknowledge the literal execution of Walter's will and transfer the house to the children. The deceased thanks in gold for the opportunity to no longer be the owner.","f":"The notary considers Walter's return a legal obstacle and does not formalize the transfer. The family continues to argue for someone else's benefit."},"E321.2":{"s":"You pay for this independent trial, and the notary finally gets time to reread the will. Walter waits patiently."},"E321.3":{"s":"{{heroName}} proves that the condition “after my death” has already occurred once and is not canceled by the resurrection. Walter thanks with gold.","f":"{{heroName}} does not find an indisputable interpretation, and the notary collects a fee. The party loses gold."},"E321.4":{"s":"You leave the children to give up their property in favor of their deceased father. The notary rubs his temples over an apparently genuine will."},"E322.1":{"s":"You find the seekers behind the inner door and take the golden purse before the tower reaches a hundred.","f":"The score reaches a critical point, and armed guards emerge from the walls. The battle begins."},"E322.2":{"s":"You quickly pick up items left at the doorstep and take supplies without adding any more steps to the tower.","f":"When you try to carry away the bags, armed guards of the counting tower appear in the opening. A skirmish begins."},"E322.3":{"s":"{{heroName}} calculates the shortest path to the abandoned items and retrieves the gold without extra steps.","f":"The walls move abruptly as the route is calculated, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The tower changes passage up to the hundredth step, but none of the eligible fighters is gravely wounded. The cache has not been reached."}},"E322.4":{"s":"You walk around the tower without helping her count to one hundred. Behind him, the whisper stops at the next number."},"E323.1":{"s":"You confirm Ark's right to purchase the family crown regardless of the presence of the head. The merchant pays in gold for the royal explanation.","f":"The merchant refuses to sell jewelry that has nowhere to be worn. Ark demands a written refusal."},"E323.2":{"s":"You buy supplies from a merchant while Ark and the squire discuss shoulder pads. The crown is still on the counter."},"E323.3":{"s":"{{heroName}} suggests that Ark wear the crown as a sign on the banner, and not on the missing head. The squire is pleased, the merchant pays in gold.","f":"{{heroName}} offers several mounting options, but Ark rejects each as unworthy of the species. The deal is not completed."},"E323.4":{"s":"You do not undertake to judge headless heraldry. Ark demands to bring him the pedigree along with the drawings of the crown."},"E324.1":{"s":"You knock on the lid three times, and a voice from the grave answers with satisfaction: “It’s in place outside.” Rufus finds a golden purse left by the stone.","f":"After the third blow, armed guards of the grave rise from the ground. A skirmish begins."},"E324.2":{"s":"You pay Rufus to tell you about yesterday's funeral, and he leads the party to the recording of the deceased. The voice from the ground continues to wait for three knocks."},"E324.3":{"s":"{{heroName}} checks the tombstone and finds a ventilation duct through which the voice passes. Rufus thanks the supplies for the peace of mind.","f":"The ground settles under {{affectedHeroName}}'s feet, causing serious injury.","v":{"nf":"The grave settles dangerously, but none of the eligible combatants are gravely wounded. The source of the voice remains unknown."}},"E324.4":{"s":"You are not answering the voice that wants to check the outside of the lid. Rufus remains near the grave with his hand raised."},"E325.1":{"s":"You pay Chass to navigate the web and receive a tidy receipt. The spider pulls up the broken thread under your feet."},"E325.2":{"s":"You cut the edge of the web and return the old road to the caravan without toll.","f":"The Spider calls for his armed defenders when you cut the bridge he built. A skirmish begins."},"E325.3":{"s":"{{heroName}} discovers that the network has blocked a public road, which means that the toll has not been agreed upon by the owners of the path. Chasse returns the gold.","f":"{{heroName}} does not find an accurate record of the right of way, and Chasse charges a fee for resolving the dispute. The party loses gold."},"E325.4":{"s":"You spend supplies to go around the canyon without paying for the spider bridge. Chasse is already writing out a receipt for the next caravan."},"E326.1":{"s":"You confirm Virra's claim: one witness and twelve - different order conditions. The guild returns the gold for the dispute.","f":"The customer calls his bodyguards, considering the decision a violation of the contract. A skirmish begins."},"E326.2":{"s":"You pay the secretary for safe passage through the guild lands. The goose sees off the party with an extremely unfriendly hiss."},"E326.3":{"s":"{{heroName}} discovers that the contract does not specify the number of witnesses and does not define the rights of the goose at all. The guild pays gold for legal clarity.","f":"{{heroName}} cannot prove that the goose was a witness, and the secretary collects legal costs. The party loses gold."},"E326.4":{"s":"You leave before the thirteenth witness appears, while Virra argues with the customer. Goose takes her place at the table."},"E327.1":{"s":"On the balcony you find a gold purse in the pocket of someone else's gloves. Narva assures that she never bought the chairs.","f":"The balcony moves to a nearby window during inspection, and {{affectedHeroName}} is severely injured.","v":{"nf":"The balcony suddenly moves, but none of the eligible fighters are gravely wounded. Other people's things stay upstairs."}},"E327.2":{"s":"You buy travel supplies from Narva and leave without touching the strange balcony. Seliss is already preparing new plans for the house."},"E327.3":{"s":"{{heroName}} finds fasteners that go not into the wall, but into the old masonry of the neighboring building. Narva thanks gold for the solution.","f":"One of the balcony's hidden supports breaks and {{affectedHeroName}} is severely injured.","v":{"nf":"The support collapses, but none of the eligible fighters are gravely wounded. The reason for the appearance of the balcony has not been found."}},"E327.4":{"s":"You leave Narva at the balcony without a door. There are already new gloves on the chair, although no one has gone upstairs."},"E328.1":{"s":"You convince Ilzara to accept the rest of the gold and let Taren leave without family intrigue. The son thanks gold for freedom.","f":"Ilzara considers simply giving away the money too simple-minded and demands that her son at least come up with a conspiracy. Negotiations break down."},"E328.2":{"s":"Taren chooses a hike where the truth can be told without family scandals. He joins the party.","f":"Taren refuses to join the new party until his mother stops looking for intrigue behind him. Can't hire him.","v":{"rs":"Taren is ready to join the party, but there is no free space. He thanks in gold for the proposed way out."}},"E328.3":{"s":"{{heroName}} convinces Ilzara to recognize direct conversation as a new form of family art. The matriarch pays in gold for Taren's peaceful departure.","f":"Ilzara denounces the negotiations as a dishonest attempt to circumvent tradition, and her guards clash."},"E328.4":{"s":"You leave Ilzar and Taren to figure out how much honesty is appropriate for their kind. The son again shows where the rest of the money is."},"E329.1":{"s":"You ask Fael a question, and the crystal gives the answer even before his mouth and opens the golden bookmark at the table.","f":"The stone utters a forbidden phrase and inflicts {{affectedHeroName}} a serious wound.","v":{"nf":"The crystal flares on the premature response, but no eligible combatants are gravely wounded. The interrogation is interrupted."}},"E329.2":{"s":"You pay the interrogator for information and leave without waiting for the next predicted answer. The stone whispers something after him."},"E329.3":{"s":"{{heroName}} determines that the crystal does not repeat a lie, but the intention to lie to the words. The interrogator thanks him with gold and supplies.","f":"The stone turns towards the researcher with a sharp blow, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The crystal disrupts the research with a dangerous flash, but none of the eligible fighters are gravely wounded. Its structure remains a mystery."}},"E329.4":{"s":"You end a conversation in which the subject speaks before the other person. For the first time, Fael looks grateful for the silence."},"E330.1":{"s":"You guide both spiders across the bridge without letting their legs touch each other. Rellis and Saar give thanks in gold for saving the wedding.","f":"The spiders collide in the middle of the bridge, and their owners call their assistants to fight. A skirmish begins."},"E330.2":{"s":"You give the newlyweds the supplies and leave them to find a way to carry out the ceremony. The priestess thanks in gold for her support."},"E330.3":{"s":"{{heroName}} calms the spiders and sees them off one after another, without requiring the animals to form a wedding formation. The priestess rewards with gold.","f":"One of the spiders suddenly rushes across the bridge, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The spiders disrupt the procession, but none of the eligible fighters are gravely wounded. The wedding is delayed."}},"E330.4":{"s":"You leave Rellis and Saar in front of two motionless spiders. The priestess already suggests holding the wedding on both sides of the bridge."},"E331.1":{"s":"You pay for a place almost at the forge and pass by indignant miners. Bela puts your name on the list, no questions asked."},"E331.2":{"s":"You convince the blacksmith line not to buy someone else's time, and the enterprising dwarf has to return some of the gold. The party gets their share.","f":"Miners find trading convenient in some places and do not want to give it up. Bela continues to get angry at the cash register."},"E331.3":{"s":"{{heroName}} negotiates with Gorm on the priority of urgent field repairs. The master returns the gold for the vacated space.","f":"{{heroName}} cannot convince Gorm to let the party through without additional payment, and they charge gold for negotiations."},"E331.4":{"s":"You pass by a blacksmith's shop where they trade in anticipation. On the road they are already offering a place in the queue to the queue seller himself."},"E332.1":{"s":"You pull the lift cage to the top level, and three miners give up gold for the rescue. Trump finally stops blaming the brakes.","f":"The rope jerks sharply, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The cage twitches dangerously, but none of the eligible combatants are gravely wounded. The miners remain between levels."}},"E332.2":{"s":"You pay Thrum for the miner's supplies and leave without waiting for the elevator to resume operation. Below they already name the price of the excursion."},"E332.3":{"s":"{{heroName}} finds the jammed brake pawl and returns the cage to motion. Grateful miners pay in gold.","f":"The lifting mechanism is sharply compressed and seriously injures {{affectedHeroName}}.","v":{"nf":"The mechanism fails repairs, but none of the eligible fighters are gravely wounded. The cage remains motionless."}},"E332.4":{"s":"You leave Trump to deal with the elevator, which defies the laws of mechanics. A demand for breakfast comes from the mine."},"E333.1":{"s":"You tell the board that good beer doesn't have to cause suffering. Hold thanks gold for protecting the recipe.","f":"Tasters refuse to recognize the drink as worthy of tradition because no one winced. The trial continues."},"E333.2":{"s":"You buy travel provisions from Hold while the council decides the fate of his beer. The brewer is happy to have at least one transaction without tasting."},"E333.3":{"s":"{{heroName}} questions the workers and finds out that the recipe has long been improved together, without trying to deceive tradition. Hold pays gold for the testimony.","f":"Workers are afraid to quarrel with the board and do not testify about the recipe. {{heroName}} returns empty-handed."},"E333.4":{"s":"You leave it to the dwarves to suffer from delicious beer. The judge waits carefully for at least one visitor to wince."},"E334.1":{"s":"You politely apologize to the safe on Farn's behalf, and the lock finally clicks. The treasurer thanks in gold for the saved cash register.","f":"The safe responds with a new message, “NOT SINCERELY ENOUGH,” and remains closed."},"E334.2":{"s":"You pay Dorrie for the supplies and leave Farn to apologize to the safe. The keys are in the lock, as before."},"E334.3":{"s":"{{heroName}} dismantles the rune mechanism without touching the security seals and opens the city safe. Farn pays the gold.","f":"The offended lock snaps the metal curtain, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The castle slams shut, but none of the eligible fighters are gravely wounded. The safe continues to demand politeness."}},"E334.4":{"s":"You wish the safe a good day and leave. A short “MUTUAL” appears on the lock plate."},"E335.1":{"s":"You wait for Keda to be the first to finish the final hit on the nail. Ault pays in gold for his patient judging.","f":"The competition drags on into the night, and the blacksmiths are not even close to finishing. There are no rewards for spectators."},"E335.2":{"s":"You buy supplies from spectators while they watch a single nail for hours. No one takes their eyes off the hammer."},"E335.3":{"s":"{{heroName}} notices that Brun improves the structure of the metal with every rare blow. Judge Ault pays in gold for the technical report.","f":"{{heroName}} can't tell the difference between two nearly identical nails. The competition continues."},"E335.4":{"s":"You leave before the nine o'clock nail is declared a sacred relic. The crowd freezes before the next blow."},"E336.1":{"s":"You follow Kern's marks and find a mountain where the map showed an empty steppe. Found ore brings gold.","f":"Instead of an ore vein, travelers find a fortified encampment of armed strangers. The battle begins."},"E336.2":{"s":"You buy back a real heavy sample of ore from Kern, without trying to find the missing mountain. Miri checks his weight again."},"E336.3":{"s":"{{heroName}} traces the first landmarks and finds a hidden cache of ore with gold and supplies.","f":"On an unmarked slope, {{affectedHeroName}} is gravely wounded by a rockfall.","v":{"nf":"The unknown slope crumbles, but none of the eligible fighters are gravely wounded. The route has to be interrupted."}},"E336.4":{"s":"You're not looking for a mountain that refuses to be on the map. Kern puts the sample in his bag and studies the empty steppe again."},"E337.1":{"s":"You buy supplies from Kezz, after carefully listening to all their shortcomings. The demon is surprised to give out the goods without a single hidden condition."},"E337.2":{"s":"You help Kezz explain to customers that fair warning is not a new trap. The demon pays gold for the saved trade.","f":"Clients mistake your participation for advertising and demand a refund for suspicious advice. The party loses gold."},"E337.3":{"s":"{{heroName}} checks the transactions and confirms: Kezz really tells the truth about each product. The grateful demon pays in gold.","f":"{{heroName}} finds that the warnings are too vague for full approval. The transactions remain suspect."},"E337.4":{"s":"You thank Kezz for the honest day and leave without purchasing anything. The demon looks longingly at the goods that he could not sell."},"E338.1":{"s":"You find the holder of ticket 666 behind the last row, and the line finally moves on. Nak pays in gold for eliminating the delay.","f":"The owner of the coupon calls for assistants, fearing immediate payment for the room. A skirmish begins."},"E338.2":{"s":"You pay Nak to pass the stuck line. The demons remain silent when number 666 is announced."},"E338.3":{"s":"{{heroName}} checks the issued coupons and finds the one who hid his number under his clothes. Nak thanks with gold.","f":"{{heroName}} finds out that the coupon was resold several times, and the trace of the owner is lost. The queue doesn't move."},"E338.4":{"s":"You go around the black arch. From a distance the receptionist’s voice can still be heard: “Number six hundred sixty-six!”"},"E339.1":{"s":"You help Rahu keep the lanterns burning until dawn, and the crimson flames calm down. The coal miner thanks with gold.","f":"At night, armed creatures emerge from the darkness, reaching for the frightened fire. A skirmish begins."},"E339.2":{"s":"You give Rahu supplies for the night march, and he pays in gold for helping his strange fire."},"E339.3":{"s":"{{heroName}} discovers that the flame is afraid not of the night, but of the cold radiation hidden in it. Rakh thanks in gold for the find.","f":"An attempt to test the properties of fire turns into a flash, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The flames erupt dangerously, but no eligible combatants are gravely wounded. The cause of the fear remains unknown."}},"E339.4":{"s":"You don't find out what the demonic flame is afraid of. Rakh again raises the lantern higher so that it does not disappear."},"E340.1":{"s":"You declare the beginning of the minute to be a witness, and the hourglass finally turns over. Azrel pays in gold for the countdown.","f":"The demon declares the decision a violation of the terms and calls for armed intermediaries. A skirmish begins."},"E340.2":{"s":"You give Azrel the gold for freeing Lorne from a minute that never began. The sand in the clock finally settles."},"E340.3":{"s":"{{heroName}} finds the legal boundary: without a starting point, there is no execution of the transaction. Azrel returns the gold for the terminated contract.","f":"{{heroName}} cannot convince the parties, and Azrel recovers the gold for the judicial review. The clock is still standing."},"E340.4":{"s":"You leave Lorne and Azrel arguing about the minute that lasts the fifth hour. The sand still doesn't fall."},"E341.1":{"s":"You help Tik collect three sincere apologies without seals or oaths. The demon pays in gold for restored dignity.","f":"Tick rejects each apology as not sincere enough and continues to make a list of debtors."},"E341.2":{"s":"You buy supplies from the innkeeper while Tick shows off his list of grievances. She asks him not to occupy his chair."},"E341.3":{"s":"{{heroName}} explains to the debtors what Tick is really waiting for and leads them to a simple conversation. The demon pays in gold for mediation.","f":"One of the debtors considers Tick's demands extortion and calls his friends. A skirmish begins."},"E341.4":{"s":"You apologize to Tick in advance for anything you could have done and leave. The demon spends a long time looking for a suitable entry in the list."},"E342.1":{"s":"You find a bug between areas 18 and 81 and force the gatekeeper to return the hell door to its designated location. Malen thanks with gold.","f":"The demon refuses to leave the approved address and calls armed portal guards. The battle begins."},"E342.2":{"s":"You buy travel supplies from Zora before the heat from the portal spoils the remaining food. The cook immediately closes the pantry."},"E342.3":{"s":"{{heroName}} removes the erroneously installed frame and closes the opening. Malen pays in gold for the returned storage room.","f":"The portal frame is hit with hot energy, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The fire frame disrupts the dismantling, but none of the eligible fighters are gravely wounded. The cheese continues to melt."}},"E342.4":{"s":"You decide to have dinner elsewhere while Malen proves to the demon the difference between 18 and 81. Zora tries to save the last piece of cheese."},"E343.1":{"s":"You convince Liel to replace the overdue rain with help for the starving peasants. The angel gives out supplies, and Tom smiles for the first time.","f":"The angel cannot change the address of an already prepared miracle and remains standing over an empty field. The village receives no help."},"E343.2":{"s":"You leave some of your own food to the peasants. Tom thanks in gold for his help without promises of miracles."},"E343.3":{"s":"{{heroName}} arranges for Liel to compensate the harvest with supplies and gold instead of rain. The village makes a decision.","f":"{{heroName}} does not find a way to turn the belated rain into a useful gift. The dispute with the angel remains open."},"E343.4":{"s":"You leave Liel and Tom in front of an empty barn. The angel still offers rain, which no one asks for anymore."},"E344.1":{"s":"You hold the heated halo while Sero straightens out the dent. Faril thanks with gold for the restored radiance.","f":"The rim slips out of its holders and {{affectedHeroName}} is severely injured.","v":{"nf":"The halo breaks when heated, but none of the eligible fighters are gravely wounded. Repairs have to be stopped."}},"E344.2":{"s":"You buy supplies from the pilgrims and leave while Faril proves his angelic nature without the halo. Cero warms up the rim again."},"E344.3":{"s":"{{heroName}} holds the shining rim on supports, and Sero finally straightens its shape. The angel thanks with gold.","f":"The hot halo breaks out of the mount and causes {{affectedHeroName}} a serious injury.","v":{"nf":"The rim is torn off its supports, but none of the eligible combatants are gravely wounded. Faril is left without a halo."}},"E344.4":{"s":"You leave Sero to repair the celestial equipment. Faril talks indignantly about the second paid entrance to his own temple."},"E345.1":{"s":"You support Iara: crime does not arise from one possible intention. The judge thanks in gold for a clear decision.","f":"Vel refuses to accept the excuse and demands a new trial of his own thoughts. The investigation is ongoing."},"E345.2":{"s":"You give supplies to a neighbor whom Vel never harmed. He thanks with gold, and Vela is advised to start with an apology."},"E345.3":{"s":"{{heroName}} helps Velu separate guilt for a thought from responsibility for an action. The judge pays in gold for a completed conversation.","f":"Vel continues to demand punishment for the unfulfilled plan, despite the explanations. The dispute is not resolved."},"E345.4":{"s":"You leave Jaru to deal with the case of a man who blames himself for something he didn't do. Vel again asks about the right to punishment."},"E346.1":{"s":"You discover that the bell is responding to a hidden crack in its own seal, not to the pilgrims. Ciel thanks the gold for the solution.","f":"Pilgrims consider the investigation an accusation of lies and are calling for armed defenders. A skirmish begins."},"E346.2":{"s":"You leave supplies for the shrine to repair the cracked bell. Ciel thanks him with gold for his help."},"E346.3":{"s":"{{heroName}} reveals an erroneous bell setting that caused it to ring for any voice. Ciel rewards with gold.","f":"The damaged seal responds with a sharp ringing sound, causing {{affectedHeroName}} a serious injury.","v":{"nf":"The bell goes off dangerously, but no eligible combatants are gravely wounded. His testimony cannot yet be trusted."}},"E346.4":{"s":"You don't test the party's integrity on a faulty bell. Ciel covers the crack with a cloth and stops receiving pilgrims."},"E347.1":{"s":"You hide Iaral in a barn and meet the hunters before they can unfurl their nets. The angel thanks with gold for protection.","f":"The hunters find the barn and call for reinforcements. The battle begins."},"E347.2":{"s":"You give Iaral the supplies and show him the hidden path from the barn. The angel thanks with gold for the opportunity to escape persecution."},"E347.3":{"s":"{{heroName}} intercepts the hunters at the fork, preventing them from reaching the barn. Iaral thanks with gold.","f":"In a hidden ambush, {{affectedHeroName}} is gravely wounded by a trapping net.","v":{"nf":"The hunters fail to intercept, but none of the eligible fighters are gravely wounded. The barn remains under threat."}},"E347.4":{"s":"You leave without interfering with the hunt for the wounded angel. Nemi closes the barn door behind Iaral."},"E348.1":{"s":"You prove that the present road exists by a later right than the ancient map of the sky. The caravan pays in gold for open passage.","f":"ES does not recognize any ground amendments to the air route. The cloud remains on the road."},"E348.2":{"s":"You pay Es for temporary passage through his low cloud. The caravan men bow their heads indignantly as they pass under the heavenly controller."},"E348.3":{"s":"{{heroName}} compares the construction date of the tract and the sky map, revealing a jurisdictional error. Es gives out gold for a resolved dispute.","f":"{{heroName}} does not find any official cancellation of the old air route. They charge gold for checking, but the cloud doesn’t go away."},"E348.4":{"s":"You walk around a low cloud along the side of the road. Es is still demanding that the carts be removed from the three-hundred-year-old sky area."},"E349.1":{"s":"You arrange the coins in piles so that the dragon's tail does not lose count, and Khar finally closes the sheet. Merchants give thanks in gold.","f":"The young dragon sneezes again at the most inopportune moment. Nobody wants to count thousands of coins again."},"E349.2":{"s":"You buy supplies from merchants awaiting the return of your deposit. Khar starts counting from the first coin once again."},"E349.3":{"s":"{{heroName}} organizes separate boxes for each coin category, leaving no room for confusion. Merchants give thanks in gold.","f":"{{heroName}} cannot get the dragon to stop moving coins, and the treasury loses gold for a failed check."},"E349.4":{"s":"You leave until the next dragon sneeze. Khar is already pronouncing the number nine thousand and ninety-nine."},"E350.1":{"s":"You ask the egg what prevents it from being born, and you finally get a meaningful answer. Raash thanks the supplies for the conversation.","f":"The shell pushes the approaching one sharply, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The egg shakes dangerously, but none of the eligible fighters are gravely wounded. You don't get an answer to the question."}},"E350.2":{"s":"You leave supplies for the keepers so they don't rush the hatching. Raash pays gold for his patience."},"E350.3":{"s":"{{heroName}} discovers that the embryo is healthy, but the magical shell is not yet ready to crack. Raasch thanks gold for the diagnosis.","f":"The protective shell gives a magical boost, and {{affectedHeroName}} is gravely wounded.","v":{"nf":"The shell repels explorers, but no eligible combatants are gravely wounded. The reason for the delay has not been established."}},"E350.4":{"s":"You leave Raash to wait for agreement from inside the huge egg. As a farewell, a firm “later” comes from there."},"E351.1":{"s":"You follow the trail of the cloak to an abandoned post and find gold there left by the provocateur. Varrash doubts the scales for the first time.","f":"The trail leads to an armed ambush by the person who planted the evidence. A skirmish begins."},"E351.2":{"s":"You give the outpost supplies for the wounded messenger, and the officer pays in gold for timely assistance."},"E351.3":{"s":"{{heroName}} compares the messenger’s testimony with the coat of arms and finds out who wanted to quarrel between the two houses. The ambassador thanks with gold for the conflict averted.","f":"{{heroName}} does not find who would benefit from leaving such obvious evidence. Varrash still demands an investigation into the intrusion."},"E351.4":{"s":"You don't get into a Draconid dispute over red scales. The wounded messenger again repeats the story of the man in the cloak."},"E352.1":{"s":"You read Marak's chronicle without missing a single ending. The old dragon thanks him in gold for a few hours of real listening.","f":"Marak stops reading after the first missing line and demands Saara's return. There will be no reward."},"E352.2":{"s":"You buy supplies from Saara before she leaves. The librarian hastily marks the page where Marak left off."},"E352.3":{"s":"{{heroName}} not only reads the chronicle, but discusses with Marak old events that he personally remembers. The dragon thanks with gold and supplies.","f":"Marak catches {{heroName}} using the wrong name on the timeline and ends the discussion. You have to read the page again."},"E352.4":{"s":"You wish the old dragon an attentive reader. Marak grumbles that a good listener should not swallow endings."},"E353.1":{"s":"You convince Rush and Kev to make the exit and storage room common, and use chalk to mark only private corners. Illa thanks with gold.","f":"Two dragons cannot even share the smoke from the fire and call for the protection of their halves. A skirmish begins."},"E353.2":{"s":"You give Illa supplies for another day of negotiations, and she pays in gold for the opportunity not to carry food over the line."},"E353.3":{"s":"{{heroName}} establishes the right of passage through the left half and access to the storage room on the right. Both dragons agree, Illa thanks with gold.","f":"{{heroName}} cannot agree on the right to an echo that can be heard throughout the cave. They demand gold for a retrial."},"E353.4":{"s":"You leave Rush and Kev to argue over who owns the smoke. Illa sits at the chalk line with a tray of food."},"E354.1":{"s":"You walk next to Cash along the suspension bridge, without rushing a single step. The courier hands over the reports and thanks them in gold.","f":"In the middle of the crossing, {{affectedHeroName}} is gravely wounded from a broken fastening.","v":{"nf":"The bridge sways dangerously, but none of the eligible combatants are gravely wounded. Cash returns to shore."}},"E354.2":{"s":"You give Kesh the supplies for the long detour, and the courier thanks you in gold for the opportunity not to cross the bridge."},"E354.3":{"s":"{{heroName}} shows Cash how to look at the far edge instead of down and guides him across the bridge. Raana thanks with gold.","f":"With a sharp gust of wind, {{affectedHeroName}} is gravely wounded.","v":{"nf":"The crossing is disrupted due to the wind, but none of the eligible fighters are gravely wounded. The reports remain on the same bank."}},"E354.4":{"s":"You leave Cash in front of a bridge that he is afraid to cross. The courier silently hides the reports deeper into his bag."},"E355.1":{"s":"You verify Rook's documents and return the sheep to the rightful shepherd. The beastman thanks him with supplies, and Bence frowns at the papers.","f":"Bence refuses to give up the sheep even after checking the documents. The dispute remains in place."},"E355.2":{"s":"You pay Ruku for the sheep and leave it to Bens, without violating the rights of the previous owner. The farmer thanks with supplies."},"E355.3":{"s":"{{heroName}} confirms Rook’s right to the flock and offers to formalize the transfer of the sheep to Bensu separately. For an accurate solution, the party is given gold.","f":"{{heroName}} discovers a discrepancy in the old drawing of the lamb, and the argument returns to square one. Gold coins are used for verification."},"E355.4":{"s":"You leave a sheep between two shepherds. She finally chews through the rope, as if deciding to exercise her own right to choose."},"E356.1":{"s":"You find a hidden passage behind a stacked woodpile and enter the inn. Mira thanks the supplies for the lucky guess.","f":"A search of all the walls yields nothing, and the carpenter Bars just shrugs from the roof. There is no dinner."},"E356.2":{"s":"You pay Mira for the hint and go through an entrance invisible from the road. The fox gives out supplies along with a hot dinner."},"E356.3":{"s":"{{heroName}} notices the cook carrying trays through the hatch under the canopy. The party gets inside and receives supplies.","f":"{{heroName}} sees only empty windows through which the plates disappear. The entrance cannot be found."},"E356.4":{"s":"You choose a tavern with ordinary doors and leave Mira to be entertained by a new circle of guests. The leopard on the roof nods approvingly."},"E357.1":{"s":"You convince Bram to allow the Fox to take only a few leaves without destroying the flower on his brother's grave. The herbalist thanks with gold.","f":"Bram does not believe that the plant will survive the cutting, and remains at his post near the only flower. There is no cure."},"E357.2":{"s":"You give the Fox supplies to search for another remedy, and she thanks you with gold for the time it will give the patient."},"E357.3":{"s":"{{heroName}} finds a way to separate the medicinal part of the root without killing the flower. Bram agrees, and Lisa pays in gold.","f":"Brahm perceives the attempt to take the flower as an attack and seriously wounds {{affectedHeroName}}.","v":{"nf":"Brahm stops the rally attempt, but none of the eligible combatants are gravely wounded. The flower remains on the grave."}},"E357.4":{"s":"You leave Bram to guard the flower on the grave. The fox asks again whether it is possible to save the patient without taking away someone else’s memory."},"E358.1":{"s":"You help Sher get to a safe house, preventing Mole from setting a new bid. Doctor Puma thanks with gold.","f":"Cher gets into another argument along the way and refuses to be accompanied. The last life remains on his conscience."},"E358.2":{"s":"You give Puma supplies to treat Sher, and she thanks you with gold for your help instead of new bets."},"E358.3":{"s":"{{heroName}} accompanies Sher to the doctor, distracting him from bookmakers and dubious duels. Puma thanks with gold.","f":"On the way to the doctor, {{affectedHeroName}} is gravely wounded while protecting Sher from new trouble.","v":{"nf":"Cher again plunges into a dangerous adventure, but none of the eligible fighters is gravely wounded. The escort stops."}},"E358.4":{"s":"You refuse to bet on Sher's last life. Mole closes the book indignantly, and Puma finally smiles."},"E359.1":{"s":"You recognize the power of the old IOU and convince Dil to begin paying off the family's debt. Omar thanks in gold for the decision.","f":"Deal denies the seventy-two-year claim and asks for a new trial. There is no agreement."},"E359.2":{"s":"You pay part of the debt in Dil's place, and Omar puts a mark on the old receipt. The merchant thanks him, but the dispute about inheriting the debt has not yet disappeared."},"E359.3":{"s":"{{heroName}} checks the signature, seals and conditions for transferring the debt to the family. Dil accepts the conclusion, Omar pays in gold for the examination.","f":"{{heroName}} discovers the disputed word in the burnt part of the receipt, and the parties demand reimbursement of expenses. The treasury is losing gold."},"E359.4":{"s":"You leave Omar with a receipt that outlives the debtor, and Dil with a family dispute. The old debt is still not repaid."},"E360.1":{"s":"You wait for Thorne to finish reading the last paragraph, and Owl shares the supplies for his patience. The bear closes the book with a heavy sigh.","f":"Thorne discovers that the novel continues with a second volume and refuses to vacate the library. The party does not get enough supplies."},"E360.2":{"s":"You buy supplies from waiting readers while a dramatic reading is heard from the library. Thorne turns another page."},"E360.3":{"s":"{{heroName}} finds out from Owl the exact number of remaining pages and helps arrange a queue for the necessary cards. Grateful visitors pay in gold.","f":"{{heroName}} finds out that Thorne has started rereading his favorite chapter. It is not possible to predict the opening time."},"E360.4":{"s":"You leave to look for cards in another library. From behind the closed door an angry voice is heard: “Don’t open it!”"}});
export { OUTCOMES_EN_E291_E360 };
